					kFloat = v
				default:
					kFloat = float64(opArr[1].(int))
				}
			}
			k := int(kFloat)
			var v interface{}
			if len(opArr) > 2 && opArr[2] != nil {
				switch val := opArr[2].(type) {
				case float64:
					v = int(val)
				case int:
					v = val
				case nil:
					v = nil
				default:
					v = val
				}
			}

