				mu.Lock()
				syncStore := make(map[int]int)
				for k, v := range store {
					syncStore[k] = v
				}
				mu.Unlock()
				body := map[string]interface{}{
					"type":  "sync",
					"store": syncStore,
				}
				_ = n.Send(other, body)
